const updateTeamLeadersSchema = z.object({
    teamId: z.string().uuid(),
    memberIds: z.array(z.string().uuid()),
});

export async function updateTeamLeaders(teamId: string, memberIds: string[]): Promise<{ error: string | null }> {
    try {
        const parsed = updateTeamLeadersSchema.safeParse({ teamId, memberIds });
        if (!parsed.success) return { error: '無効なパラメータです。' };

        await checkAdmin();
        const supabase = await createClient();
        const supabaseAdmin = await createAdminClient();

        // Find old leaders to sync their roles later
        const { data: oldLeadersData, error: oldLeadersError } = await supabaseAdmin.from('team_leaders')
            .select('member_id')
            .eq('team_id', teamId);

        if (oldLeadersError) throw oldLeadersError;

        const oldLeaderIds = oldLeadersData.map(l => l.member_id);

        const { error: deleteError } = await supabaseAdmin.from('team_leaders').delete().eq('team_id', teamId);
        if (deleteError) throw deleteError;

        if (memberIds.length > 0) {
            const newLeaders = memberIds.map(member_id => ({ team_id: teamId, member_id }));
            const { error: insertError } = await supabaseAdmin.from('team_leaders').insert(newLeaders);
            if (insertError) throw insertError;
        }

        const idsToSync = [...new Set([...oldLeaderIds, ...memberIds])];

        if (idsToSync.length > 0) {
            const { data: membersToSync, error: membersError } = await supabase.from('members')
                .select('discord_uid')
                .in('supabase_auth_user_id', idsToSync);

            if (membersError) throw membersError;

            if (membersToSync) {
                 console.log(`[Discord Bot] Syncing roles for ${membersToSync.length} members affected by leader change in team ${teamId}`);
                for (const member of membersToSync) {
                    await syncDiscordRoles(member.discord_uid);
                }
            }
        }

        revalidatePath('/dashboard/admin/teams');
        return { error: null };
    } catch (e: any) {
        console.error("Error updating team leaders:", e);
        return { error: e.message };
    }
}

